function leaderDrafts(before: GameState, after: GameState): Draft[] {
  if (before.factions === undefined || after.factions === undefined || before.factions === after.factions) return [];
  const past = new Set((after.persons?.past ?? []).filter(person => !person.alive).map(person => person.id));
  return after.factions.factions.flatMap(faction => {
    const was = before.factions!.factions.find(entry => entry.id === faction.id)?.leaderId ?? null;
    if (was === null || faction.leaderId === null || was === faction.leaderId || !past.has(was)) return [];
    return [{ tick: after.tick, kind: "faction" as const, template: "faction.leader_succeeded", subject: { type: "faction" as const, id: faction.id },
      params: { faction: faction.id, name: faction.name, predecessorId: was, leaderId: faction.leaderId }, severity: 1 as const }];
  });
}

// FIX-11 (FX11-1): wardship begin and end — the ward is the lord the rule reads (`manorLord`), before or after.
const lordOf = (state: GameState) => manorLord(state.persons?.people ?? [], lordshipOf(state).house.order, currentYear(state));
if (was.wardship === undefined && now.wardship !== undefined) {
  const lord = lordOf(after);
  const guardianId = now.wardship.guardianId;
  const guardian = guardianId === null ? undefined : after.persons?.people.find(person => person.id === guardianId);
  drafts.push({ tick: after.tick, kind: "milestone", template: "lord.wardship_begun",
    params: { lordId: lord?.id ?? "", guardianId: guardian?.id ?? "" },
    subject: TOWN, severity: 2 });
} else if (was.wardship !== undefined && now.wardship === undefined) {
  const lord = lordOf(after) ?? lordOf(before);
  drafts.push({ tick: after.tick, kind: "milestone", template: "lord.wardship_ended",
    params: { lordId: lord?.id ?? "" },
    subject: TOWN, severity: 2 });
}

function stewardshipDrafts(before: GameState, after: GameState): Draft[] {
  if (after.stewardship === before.stewardship || after.stewardship === undefined) return [];
  const was = before.stewardship;
  const now = after.stewardship;
  const drafts: Draft[] = [];
  const house = (estateId: string) => estatesOf(after).estates.find(estate => estate.id === estateId)?.name ?? estateId;
  const line = (template: string, params: Record<string, string | number>, severity: 0 | 1 | 2 = 1) =>
    drafts.push({ tick: after.tick, kind: "event", template, subject: TOWN, severity, params });
  for (const oversight of now.oversight) {
    if (was?.oversight.some(entry => entry.estateId === oversight.estateId) !== true) {
      line("stewardship.began", { estate: oversight.estateId, house: house(oversight.estateId), stewardId: oversight.stewardId }, 2);
    }
    // FIX-13 (ES-11): the steward died; the next one serves.
    const prior = was?.oversight.find(entry => entry.estateId === oversight.estateId);
    if (prior !== undefined && prior.stewardId !== oversight.stewardId && now.stewards.find(entry => entry.personId === prior.stewardId)?.status === "dead") {
      line("stewardship.steward_died", { house: house(oversight.estateId), deceasedId: prior.stewardId, stewardId: oversight.stewardId }, 2);
    }

/** FIX-11: find the guardian for a minor lord (mother → adult blood kin → null = overlord wardship). */
function findWardshipGuardian(state: GameState, lord: Person, houseOrder: number): string | null {
  const year = currentYear(state);
  const manorPeople = (state.persons?.people ?? []).filter(p => p.householdId === MANOR_HOUSEHOLD);
  const houseTag = `lord-house:${houseOrder}`;
  const mother = manorPeople.find(p => p.sex === "female" && p.role === "spouse");
  if (mother !== undefined) return mother.id;
  const kin = manorPeople.find(p => p.tags.includes(houseTag) && p.id !== lord.id && ageOf(p, year) >= WARDSHIP_AGE_YEARS);
  if (kin !== undefined) return kin.id;
  return null;
}

/** FIX-11: begin wardship for a minor lord — sets guardianId in lordship state. */
export function beginWardship(state: GameState, tick: number, lord: Person): GameState {
  const lordship = lordshipOf(state);
  const guardianId = findWardshipGuardian(state, lord, lordship.house.order);
  return { ...state, lordship: { ...lordship, wardship: { guardianId, since: tick } } };

// FIX-11: wardship — yearly check for minor lord start/end.
if (state.tick % YEAR === 0) {
  const year = currentYear(next);
  const lord = manorLord(next.persons?.people ?? [], lordship.house.order, year);
  if (lord !== undefined && ageOf(lord, year) < WARDSHIP_AGE_YEARS && lordship.wardship === undefined) {
    lordship = { ...lordship, wardship: { guardianId: findWardshipGuardian(next, lord, lordship.house.order), since: state.tick } };
    next = { ...next, lordship };
  } else if (lord !== undefined && ageOf(lord, year) >= WARDSHIP_AGE_YEARS && lordship.wardship !== undefined) {
    const { wardship: _w, ...rest } = lordship;
    lordship = rest;
    next = { ...next, lordship };
  }

/** The estates off the map the lord holds now (title and possession). */
export function heldOffMapEstates(state: GameState): readonly Estate[] {
  return state.estates === undefined ? [] : estatesOf(state).estates.filter(estate => estate.offMap && estate.possessor === LORD && estate.titleHolder === LORD);
}

/** SW-2: the estates the lord came to hold get their oversight (direct, the most loyal candidate keeping the accounts). */
function ensureOversight(state: GameState): GameState {
  const held = heldOffMapEstates(state);
  const current = stewardshipOf(state);
  const missing = held.filter(estate => !current.oversight.some(entry => entry.estateId === estate.id));
  if (missing.length === 0) return state;
  let next = state;
  let stewardship = current;
  for (const estate of missing) {
    const made = makeCandidates(next, estate.id);
    const receiver = [...made.stewards].sort((a, b) => b.loyalty - a.loyalty || a.personId.localeCompare(b.personId))[0]!;
    next = { ...next, estates: { ...estatesOf(next), people: [...estatesOf(next).people, ...made.people] } };
    stewardship = { ...stewardship, stewards: [...stewardship.stewards, ...made.stewards.map(record => record === receiver ? { ...record, status: "serving" as const } : record)],
      oversight: [...stewardship.oversight, { estateId: estate.id, mode: "direct", stewardId: receiver.personId, auditMode: "accounts", tenants: 0, merchants: 0,
      undetected: 0, since: state.tick }] };
  }
  return withStewardship(next, stewardship);
}

/**
 * FIX-13 (ES-11): a steward (or a direct estate's receiver) who died by the table is replaced at the season's turn — the
 * most loyal living candidate serves; with none left a fresh round of three is drawn. The mode stays.
 */
function replaceDeadStewards(state: GameState): GameState {
  let next = state;
  for (const oversight of stewardshipOf(state).oversight) {
    const people = estatesOf(next).people;
    if (people.find(person => person.id === oversight.stewardId)?.alive !== false) continue;
    let stewardship = stewardshipOf(next);
    stewardship = withSteward(stewardship, { ...steward(stewardship, oversight.stewardId)!, status: "dead" });
    const living = (records: readonly StewardRecord[]) => records.filter(entry => entry.estateId === oversight.estateId && entry.status === "candidate"
      && estatesOf(next).people.find(person => person.id === entry.personId)?.alive !== false);
    if (living(stewardship.stewards).length === 0) {
      const made = makeCandidates(withStewardship(next, stewardship), oversight.estateId);
      next = { ...next, estates: { ...estatesOf(next), people: [...estatesOf(next).people, ...made.people] } };
      stewardship = { ...stewardship, stewards: [...stewardship.stewards, ...made.stewards] };
    }
    const successor = [...living(stewardship.stewards)].sort((a, b) => b.loyalty - a.loyalty || a.personId.localeCompare(b.personId))[0]!;
    stewardship = withOversight(withSteward(stewardship, { ...successor, status: "serving", since: state.tick }), { ...oversight, stewardId: successor.personId, since: state.tick });
    next = withStewardship(next, stewardship);
  }
  return next;

/** FX-2: the town's heads a town faction may be led by, best first (merchant houses: merchants; the town: artisans; the commons: the reeve). */
function townCandidates(state: Pick<GameState, "persons" | "seed" | "tick" | "scenarioId">, def: FactionDef): readonly Person[] {
  const all = (state.persons?.people ?? []).filter(person => person.role === "head" && person.householdId !== "manor");
  // FIX-9: a head old enough for the role (the town community's 30, a merchant's 25), while the town has one.
  const year = currentYear(state);
  const grown = all.filter(person => ageOf(person, year) >= FACTION_LEADER_MIN_AGE[def.id]);
  const heads = grown.length > 0 ? grown : all;
  const rank: Readonly<Record<string, readonly string[]>> = {
    merchant_house: ["merchant", "artisan", "labour", "poor_servant"], town: ["artisan", "merchant", "labour", "poor_servant"], commons: ["labour", "poor_servant", "artisan", "merchant"],
  };
  const order = rank[def.kind] ?? [];
  const key = (person: Person) => (def.kind === "commons" && person.tags.includes("reeve") ? -1 : order.indexOf(person.classBand) === -1 ? 9 : order.indexOf(person.classBand));
  return [...heads].sort((a, b) => key(a) - key(b) || hashSeed(state.seed, `leader:${def.id}`, Number(a.id.slice(2))) - hashSeed(state.seed, `leader:${def.id}`, Number(b.id.slice(2))));
}

/** FX-2: the town factions' leaders — kept while they live in the town, else the best head not leading another town faction. */
function townLeaders(state: Pick<GameState, "persons" | "seed" | "tick" | "scenarioId">, factions: readonly FactionRecord[]): Map<FactionId, Person | null> {
  const living = new Map((state.persons?.people ?? []).map(person => [person.id, person]));
  const taken = new Set<string>();
  const result = new Map<FactionId, Person | null>();
  for (const def of FACTION_DEFS.filter(entry => entry.leaders === "town")) {
    const current = factions.find(faction => faction.id === def.id)?.leaderId;
    const kept = current == null ? undefined : living.get(current);
    // The second merchant house is another family (another surname) than the first.
    const firstSurname = def.id === "merchant_house_2" ? living.get(result.get("merchant_house_1")?.id ?? "")?.surname : undefined;
    const leader = kept !== undefined && kept.role === "head" && !taken.has(kept.id) ? kept
      : townCandidates(state, def).find(person => !taken.has(person.id) && (firstSurname === undefined || person.surname !== firstSurname)) ?? null;
    if (leader !== null) taken.add(leader.id);
    result.set(def.id, leader);
  }
  return result;
}

/** FIX-12 (item 3): the town factions whose leader is no longer among the living get the next head (`townLeaders`). */
function followDeadTownLeaders(state: GameState, current: FactionState): FactionState {
  if (state.tick % SEASON !== 1 && !state.houses.some(house => house.burntTick === state.tick)) return current;
  const living = new Set((state.persons?.people ?? []).map(person => person.id));
  const dead = (faction: FactionRecord) => FACTION_DEF_BY_ID.get(faction.id)?.leaders === "town" && faction.leaderId !== null && !living.has(faction.leaderId);
  if (!current.factions.some(dead)) return current;
  const leaders = townLeaders(state, current.factions.map(faction => dead(faction) ? { ...faction, leaderId: null } : faction));
  const year = currentYear(state);
  return { ...current, factions: current.factions.map(faction => {
    if (!dead(faction)) return faction;
    const leader = leaders.get(faction.id) ?? null;
    const def = FACTION_DEFS.find(entry => entry.id === faction.id)!;
    return { ...faction, leaderId: leader?.id ?? null, name: townFactionName(def, leader),
      timeline: leader === null ? faction.timeline : [...faction.timeline, { tick: state.tick, year, kind: "leader" as const, id: "succeeded", personId: leader.id }] };
  }) };
}

